def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Template is the longest horizontal run of non-background cells.
    runs=[]
    for r,row in enumerate(grid):
        c=0
        while c<w:
            if row[c]==bg:
                c+=1; continue
            start=c
            while c<w and row[c]!=bg: c+=1
            runs.append((c-start,r,start,row[start:c]))
    length,sr,sc,motif=max(runs)
    out=[row[:] for row in grid]
    # Isolated non-background cells are destination markers; leave template intact.
    seen=set(); markers=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            stack=[(r,c)];seen.add((r,c));comp=[]
            while stack:
                rr,cc=stack.pop();comp.append((rr,cc))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=rr+dr,cc+dc
                    if 0<=nr<h and 0<=nc<w and grid[nr][nc]!=bg and (nr,nc) not in seen:
                        seen.add((nr,nc));stack.append((nr,nc))
            if len(comp)==1 and comp[0] not in {(sr,sc+i) for i in range(length)}:
                markers.append(comp[0])
    center=length//2
    for r,c in markers:
        for i,v in enumerate(motif):
            cc=c+i-center
            if 0<=cc<w: out[r][cc]=v
    return out
